// Capability probe only: exact native cuBLASLt descriptor contract, no matrix computation or timing claimed.
#define main original_hecbench_main
#include "../blas-mxfp6gemm-cuda/main.cu"
#undef main
#include <dlfcn.h>
int main(){cudaDeviceProp prop;cudaGetDeviceProperties(&prop,0);printf("GPU %s sm%d%d cuBLASLt_version=%zu\n",prop.name,prop.major,prop.minor,cublasLtGetVersion());Dl_info info={};dladdr(dlsym(RTLD_DEFAULT,"cublasLtGetVersion"),&info);printf("LOADED_CUBLASLT %s\n",info.dli_fname?info.dli_fname:"unknown");cublasLtHandle_t h;auto create=cublasLtCreate(&h);if(create){printf("create_status=%d\n",create);return 2;}unsigned char*scale;cudaMalloc(&scale,128);cudaMemset(scale,127,128);
const int dims[6][3]={{128,128,128},{8192,8192,512},{8192,8192,1024},{8192,8192,2048},{8192,8192,4096},{8192,8192,8192}};
for(auto&shape:dims){int m=shape[0],n=shape[1],k=shape[2];cublasLtMatmulDesc_t op;checkCublasStatus(cublasLtMatmulDescCreate(&op,CUBLAS_COMPUTE_32F,CUDA_R_32F));cublasOperation_t ta=CUBLAS_OP_T,tb=CUBLAS_OP_N;checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_TRANSA,&ta,sizeof(ta)));checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_TRANSB,&tb,sizeof(tb)));checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_A_SCALE_POINTER,&scale,sizeof(scale)));checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_B_SCALE_POINTER,&scale,sizeof(scale)));cublasLtMatmulMatrixScale_t scaleMode=CUBLASLT_MATMUL_MATRIX_SCALE_VEC32_UE8M0;checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_A_SCALE_MODE,&scaleMode,sizeof(scaleMode)));checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_B_SCALE_MODE,&scaleMode,sizeof(scaleMode)));
cublasLtMatrixLayout_t A,B,C,D;checkCublasStatus(cublasLtMatrixLayoutCreate(&A,CUDA_R_6F_E2M3,k,m,k));checkCublasStatus(cublasLtMatrixLayoutCreate(&B,CUDA_R_6F_E2M3,k,n,k));checkCublasStatus(cublasLtMatrixLayoutCreate(&C,CUDA_R_16BF,m,n,m));checkCublasStatus(cublasLtMatrixLayoutCreate(&D,CUDA_R_16BF,m,n,m));cublasLtMatmulPreference_t pref;checkCublasStatus(cublasLtMatmulPreferenceCreate(&pref));size_t workspace=32*1024*1024;checkCublasStatus(cublasLtMatmulPreferenceSetAttribute(pref,CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,&workspace,sizeof(workspace)));cublasLtMatmulHeuristicResult_t result={};int returned=-1;auto status=cublasLtMatmulAlgoGetHeuristic(h,op,A,B,C,D,pref,1,&result,&returned);printf("CAPABILITY_CASE m=%d n=%d k=%d heuristic_status=%d returned_algorithms=%d\n",m,n,k,status,returned);cublasLtMatmulPreferenceDestroy(pref);cublasLtMatrixLayoutDestroy(A);cublasLtMatrixLayoutDestroy(B);cublasLtMatrixLayoutDestroy(C);cublasLtMatrixLayoutDestroy(D);cublasLtMatmulDescDestroy(op);
}cudaFree(scale);cublasLtDestroy(h);return 0;}
